-            }
-
-            /* done with ephemeral key */
-            wolfTPM2_UnloadHandle(tlsCtx->dev, &tlsCtx->ecdhKey->handle);
-        #endif /* !WOLFTPM2_USE_SW_ECDHE */
-        }
-    #endif /* HAVE_ECC */
-    }
-#endif /* !NO_RSA || HAVE_ECC */
-#ifndef NO_AES
-    else if (info->algo_type == WC_ALGO_TYPE_CIPHER) {
