+import React from "react";
+import { Badge } from "@/components/ui/badge";
+import { Button } from "@/components/ui/button";
+import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
+import { AlertCircle, RefreshCw } from "lucide-react";
+import CopyButton from "@/components/CopyButton";
+
+interface ServerStatusSectionProps {
+  status: "running" | "starting" | "error" | "stopped";
+  url?: string;
+  error?: Error | string | null;
+  serverName: string;
+  transport: string;
+  refreshStatus: () => void;
+}
+
+export const ServerStatusSection: React.FC<ServerStatusSectionProps> = ({
+  status,
+  url,
+  error,
+  serverName,
+  transport,
+  refreshStatus,
+}) => {
+  if (status === "running") {
+    return (
+      <div className="space-y-6">
+        {/* Server Status Section */}
+        <div className="flex items-center justify-between mb-4">
+          <div>
+            <h2 className="text-xl font-bold">{serverName} MCP Server</h2>
+            <p className="text-muted-foreground text-sm">Transport: {transport}</p>
+          </div>
+          <Badge className="bg-green-100 text-green-800 hover:bg-green-200 transition-colors">
+            <span className="h-2 w-2 rounded-full bg-green-500 mr-1.5 inline-block"></span>
+            Running
+          </Badge>
+        </div>
+        
+        <div className="flex items-center justify-between p-3 border rounded-md">
+          <code className="text-sm font-mono">{url}</code>
+          <div className="flex items-center gap-2">
+            <CopyButton content={url || ""} />
+          </div>
+        </div>
+        
+        <div className="flex justify-end mt-4">
+          <Button onClick={refreshStatus} variant="outline" size="sm" className="gap-1">
+            <RefreshCw className="h-3.5 w-3.5" />
+            Refresh Status
+          </Button>
+        </div>
+      </div>
+    );
+  }
+
+  if (status === "starting") {
+    return (
+      <div>
+        <h2 className="text-xl font-bold mb-4">MCP Server Status</h2>
+        <Alert className="bg-yellow-50 border-yellow-500">
+          <AlertCircle className="h-4 w-4 text-yellow-500" />
+          <AlertTitle className="text-yellow-700">Server is starting</AlertTitle>
+          <AlertDescription className="text-yellow-600">
+            Your MCP server is currently starting up. Please wait a moment...
+          </AlertDescription>
+        </Alert>
+        <div className="flex justify-end mt-4">
+          <Button onClick={refreshStatus} className="gap-1">
+            <RefreshCw className="h-3.5 w-3.5" />
+            Refresh Status
+          </Button>
+        </div>
+      </div>
+    );
+  }
+
+  if (status === "error") {
+    return (
+      <div>
+        <h2 className="text-xl font-bold mb-4">MCP Server Status</h2>
+        <Alert variant="destructive" className="border-red-500">
+          <AlertCircle className="h-4 w-4" />
+          <AlertTitle>Server error</AlertTitle>
+          <AlertDescription>
+            {error instanceof Error ? error.message : error ? String(error) : "There was an error starting your MCP server."}
+          </AlertDescription>
+        </Alert>
+        <div className="flex justify-end mt-4">
+          <Button onClick={refreshStatus} variant="outline" className="gap-1">
+            <RefreshCw className="h-3.5 w-3.5" />
+            Refresh Status
+          </Button>
+        </div>
+      </div>
+    );
+  }
+
+  // Default case: server is stopped
+  return (
+    <div>
+      <h2 className="text-xl font-bold mb-4">MCP Server Status</h2>
+      <Alert className="border-gray-400">
+        <AlertCircle className="h-4 w-4" />
+        <AlertTitle>Server is not running</AlertTitle>
+        <AlertDescription>
+          Your MCP server is currently stopped. Start the server to access it.
+        </AlertDescription>
+      </Alert>
+      <div className="flex justify-end mt-4">
+        <Button onClick={refreshStatus} variant="outline" className="gap-1">
+          <RefreshCw className="h-3.5 w-3.5" />
+          Refresh Status
+        </Button>
+      </div>
+    </div>
+  );
+};'}, {'filename': 'src/components/mcp-explorer/ToolParameterSchema.tsx', 'status': 'added', 'patch': '@@ -0,0 +1,42 @@
+import React, { useState } from "react";
+import { Button } from "@/components/ui/button";
+import { SchemaDialog } from "@/components/api-explorer/SchemaDialog";
+
+interface ToolParameterSchemaProps {
+  schema: any;
+  name: string;
+}
+
+export const ToolParameterSchema: React.FC<ToolParameterSchemaProps> = ({ schema, name }) => {
+  const [dialogOpen, setDialogOpen] = useState(false);
+  
+  const isObject = schema.type === 'object' || (schema.properties && Object.keys(schema.properties).length > 0);
+  const isArray = schema.type === 'array' && schema.items;
+  const hasComplexItems = isArray && (
+    schema.items && (schema.items.type === 'object' || schema.items.properties)
+  );
+  
+  const canViewSchema = isObject || hasComplexItems;
+  
+  return (
+    <div>
+      <Button 
+        variant="ghost" 
+        size="sm" 
+        className="h-6 px-2 text-xs"
+        onClick={() => setDialogOpen(true)}
+      >
+        View Schema
+      </Button>
+      
+      {canViewSchema && (
+        <SchemaDialog
+          open={dialogOpen}
+          onOpenChange={setDialogOpen}
+          schema={schema}
+          title={`${name} Schema`}
+        />
+      )}
+    </div>
+  );
+};'}, {'filename': 'src/components/mcp-explorer/ToolsList.tsx', 'status': 'added', 'patch': '@@ -0,0 +1,77 @@
+import React from "react";
+import { Tool } from "@modelcontextprotocol/sdk/types";
+import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from "@/components/ui/accordion";
+import { Badge } from "@/components/ui/badge";
+import { ToolParameterSchema } from "./ToolParameterSchema";
+import { extractToolParameters } from "./utils";
+
+interface ToolsListProps {
+  tools: Tool[];
+}
+
+export const ToolsList: React.FC<ToolsListProps> = ({ tools }) => {
+  if (tools.length === 0) {
+    return null;
+  }
+
+  return (
+    <div className="space-y-6">
+      <div className="mb-4">
+        <h2 className="text-xl font-bold">Available MCP Tools</h2>
+        <p className="text-muted-foreground text-sm">Expand a tool to view its details and parameters</p>
+      </div>
+      
+      <Accordion type="single" collapsible className="w-full">
+        {tools.map((tool, index) => (
+          <AccordionItem key={tool.name} value={`tool-${index}`} className="border-t">
+            <AccordionTrigger className="hover:no-underline">
+              <div className="flex flex-col items-start gap-1 text-left w-full">
+                <span className="font-medium">{tool.name}</span>
+                {tool.description && (
+                  <p className="text-sm text-muted-foreground font-normal">{tool.description}</p>
+                )}
+              </div>
+            </AccordionTrigger>
+            <AccordionContent>
