+/* Markdown content styling */
+.markdown-content {
+  color: hsl(var(--foreground));
+  line-height: 1.5;
+  font-size: 0.875rem;
+  font-family: var(--font-sans);
+}
+
+/* Headings */
+.markdown-content h1 {
+  font-size: 1.5rem;
+  font-weight: 700;
+  margin-top: 1.25rem;
+  margin-bottom: 0.75rem;
+  border-bottom: 1px solid hsl(var(--border));
+  padding-bottom: 0.375rem;
+  color: hsl(var(--foreground));
+}
+
+.markdown-content h2 {
+  font-size: 1.25rem;
+  font-weight: 600;
+  margin-top: 1.25rem;
+  margin-bottom: 0.625rem;
+  color: hsl(var(--foreground));
+}
+
+.markdown-content h3 {
+  font-size: 1.125rem;
+  font-weight: 600;
+  margin-top: 1rem;
+  margin-bottom: 0.625rem;
+  color: hsl(var(--foreground));
+}
+
+.markdown-content h4 {
+  font-size: 1rem;
+  font-weight: 600;
+  margin-top: 0.875rem;
+  margin-bottom: 0.5rem;
+  color: hsl(var(--foreground));
+}
+
+.markdown-content h5, .markdown-content h6 {
+  font-size: 0.875rem;
+  font-weight: 600;
+  margin-top: 0.875rem;
+  margin-bottom: 0.375rem;
+  color: hsl(var(--foreground));
+}
+
+/* Paragraphs and lists */
+.markdown-content p {
+  margin-bottom: 1rem;
+  color: hsl(var(--foreground));
+}
+
+.markdown-content ul, .markdown-content ol {
+  margin-bottom: 1rem;
+  padding-left: 1.5rem;
+}
+
+.markdown-content li {
+  margin-bottom: 0.25rem;
+}
+
+.markdown-content ul li {
+  list-style-type: disc;
+}
+
+.markdown-content ol li {
+  list-style-type: decimal;
+}
+
+/* Links */
+.markdown-content a {
+  color: hsl(var(--primary));
+  text-decoration: underline;
+  text-underline-offset: 2px;
+}
+
+.markdown-content a:hover {
+  text-decoration: none;
+}
+
+/* Blockquotes */
+.markdown-content blockquote {
+  border-left: 4px solid hsl(var(--border));
+  padding-left: 1rem;
+  margin-left: 0;
+  margin-right: 0;
+  font-style: italic;
+  color: hsl(var(--muted-foreground));
+}
+
+/* Code blocks */
+.markdown-content pre {
+  background-color: transparent;
+  border-radius: var(--radius);
+  padding: 1.5rem 1rem;
+  margin: 1.5rem 0;
+  overflow-x: auto;
+  position: relative;
+  border: 1px solid hsl(var(--border));
+}
+
+/* Language indicator */
+.markdown-content pre::before {
+  content: attr(data-language);
+  position: absolute;
+  top: 0.5rem;
+  left: 0.75rem;
+  font-size: 0.75rem;
+  color: hsl(var(--muted-foreground));
+  font-family: ui-sans-serif, system-ui, sans-serif;
+  z-index: 10;
+  padding: 0.125rem 0.25rem;
+  text-transform: lowercase;
+  letter-spacing: 0.05em;
+  font-weight: 500;
+}
+
+.markdown-content code {
+  font-family: var(--font-mono);
+  font-size: 0.9em;
+  line-height: 1.6;
+}
+
+/* Command line styling */
+.markdown-content pre code {
+  display: block;
+  padding-top: 0.75rem;
+}
+
+.markdown-content pre code .hljs-comment,
+.markdown-content pre code .hljs-meta {
+  color: #75715e;
+}
+
+.markdown-content pre code .hljs-string {
+  color: #a6e22e;
+}
+
+.markdown-content pre code .hljs-keyword {
+  color: #f92672;
+}
+
+/* Copy button */
+.markdown-content pre .copy-button {
+  position: absolute;
+  right: 0.75rem;
+  top: 0.5rem;
+  background: hsl(var(--accent));
+  border: none;
+  border-radius: var(--radius-sm);
+  color: hsl(var(--accent-foreground));
+  padding: 0.125rem 0.5rem;
+  font-size: 0.75rem;
+  cursor: pointer;
+  transition: all 0.2s ease;
+  opacity: 0;
+  z-index: 20;
+}
+
+.markdown-content pre:hover .copy-button {
+  opacity: 1;
+}
+
+.markdown-content pre .copy-button:hover {
+  background: hsl(var(--accent-foreground));
+  color: hsl(var(--accent));
+}
+
+.markdown-content pre .copy-button.copied {
+  background-color: hsl(var(--primary));
+  color: hsl(var(--primary-foreground));
+}
+
+.markdown-content p code, 
+.markdown-content li code, 
+.markdown-content td code {
+  background-color: hsl(var(--muted));
+  color: hsl(var(--muted-foreground));
+  padding: 0.2em 0.4em;
+  border-radius: var(--radius-sm);
+}
+
+/* Tables */
+.markdown-content table {
+  width: 100%;
+  border-collapse: collapse;
+  margin: 1rem 0;
+}
+
+.markdown-content th, .markdown-content td {
+  border: 1px solid hsl(var(--border));
+  padding: 0.5rem;
+}
+
+.markdown-content th {
+  background-color: hsl(var(--muted));
+  color: hsl(var(--muted-foreground));
+  font-weight: 600;
+}
+
+/* Images */
+.markdown-content img {
+  max-width: 100%;
+  height: auto;
+  border-radius: 0.375rem;
+}
+
+/* Horizontal rule */
+.markdown-content hr {
+  border: none;
+  border-top: 1px solid var(--border);
+  margin: 1.5rem 0;
+}'}, {'filename': 'src/types/markdown-it.d.ts', 'status': 'added', 'patch': "@@ -0,0 +1,20 @@
+declare module 'markdown-it' {
+  interface MarkdownItOptions {
+    html?: boolean;
+    xhtmlOut?: boolean;
+    breaks?: boolean;
+    langPrefix?: string;
+    linkify?: boolean;
+    typographer?: boolean;
+    quotes?: string;
+    highlight?: (str: string, lang: string) => string | undefined;
+  }
+
+  class MarkdownIt {
+    constructor(options?: MarkdownItOptions | string);
+    render(md: string): string;
+    renderInline(md: string): string;
+  }
+
+  export default MarkdownIt;
+}"}]

