+
+const getLanguageExtension = (language?: string) => {
+  switch (language?.toLowerCase()) {
+    case "javascript":
+    case "js":
+    case "typescript":
+    case "ts":
+      return javascript({ typescript: true });
+    case "json":
+      return json();
+    case "yaml":
+      return yaml();
+    case "html":
+      return html();
+    case "css":
+      return css();
+    case "python":
+      return python();
+    default:
+      return markdown({
+        codeLanguages: languages,
+        addKeymap: true,
+      });
+  }
+};
+
+interface Props {
+  editorRef?: RefObject<EditorView | null>;
+  defaultValue?: string;
+  height?: string | number;
+  fontSize?: number;
+  language?: string;
+  readOnly?: boolean;
+  autoFocus?: boolean;
+  overflowHidden?: boolean;
+  testId?: string;
+  additionalExtensions?: Extension[];
+  onChange?: (value: string) => void;
+  onFocusChange?: (focused: boolean, viewUpdate: ViewUpdate) => void;
+  onMount?: (view: EditorView) => void;
+}
+
+export default function CodeMirrorEditor({
+  editorRef,
+  defaultValue,
+  height,
+  fontSize,
+  language,
+  readOnly,
+  autoFocus,
+  testId,
+  overflowHidden,
+  additionalExtensions,
+  onChange,
+  onFocusChange,
+  onMount,
+}: Props) {
+  const editorContainerRef = useRef<HTMLDivElement>(null);
+  const internalEditorRef = useRef<EditorView | null>(null);
+  
+  const isDarkTheme = React.useMemo(() => {
+    return document.documentElement.classList.contains("dark") ? "dark" : "light";
+  }, []);
+
+  // Use provided ref or internal ref
+  const actualEditorRef = editorRef || internalEditorRef;
+
+  function focusAtEndOfContent(editor: EditorView) {
+    const doc = editor.state.doc;
+    const endPos = doc.length;
+    editor.dispatch({
+      selection: { anchor: endPos, head: endPos },
+    });
+    editor.focus();
+  }
+
+  useEffect(() => {
+    if (!editorContainerRef.current) return;
+
+    const editorTheme = EditorView.theme({
+      "&": {
+        fontSize: `${fontSize || 13}px`,
+        fontFamily: "var(--font-mono)",
+        height: "100%",
+        backgroundColor: "transparent",
+      },
+      ".cm-content": {
+        fontFamily: "var(--font-mono)",
+      },
+      ".cm-scroller": {
+        overflow: overflowHidden ? "hidden" : "auto",
+      },
+      "&.cm-focused": {
+        outline: "none",
+      },
+      ".cm-cursor": {
+        borderLeftColor: "hsl(var(--foreground))",
+      },
+      ".cm-line": {
+        padding: "0",
+        color: "hsl(var(--foreground))",
+      },
+      "&.cm-focused > .cm-scroller > .cm-selectionLayer .cm-selectionBackground, .cm-selectionBackground, .cm-content ::selection":
+        {
+          background: "hsl(var(--accent))",
+        },
+    });
+
+    const themeExtension =isDarkTheme ? vscodeDark : vscodeLight;
+
+    const customExtensions = [
+      ...(additionalExtensions || []),
+      drawSelection(),
+      history(),
+      EditorView.lineWrapping,
+      EditorView.updateListener.of((viewUpdate) => {
+        if (viewUpdate.docChanged) {
+          const value = viewUpdate.state.doc.toString();
+          onChange?.(value);
+        }
+        if (viewUpdate.focusChanged) {
+          onFocusChange?.(viewUpdate.view.hasFocus, viewUpdate);
+        }
+      }),
+      editorTheme,
+      themeExtension,
+      getLanguageExtension(language),
+      EditorState.readOnly.of(!!readOnly),
+      keymap.of([...defaultKeymap, ...historyKeymap]),
+    ];
+
+    // Initialize CodeMirror with extensions
+    const startState = EditorState.create({
+      doc: defaultValue,
+      extensions: customExtensions,
+    });
+
+    // Create editor view
+    const view = new EditorView({
+      state: startState,
+      parent: editorContainerRef.current,
+    });
+
+    actualEditorRef.current = view;
+
+    onMount?.(view);
+
+    if (autoFocus) {
+      setTimeout(() => focusAtEndOfContent(view), 0);
+    }
+
+    return () => {
+      view.destroy();
+      actualEditorRef.current = null;
+    };
+  }, [defaultValue, language]);
+
+  return (
+    <div
+      ref={editorContainerRef}
+      data-testid={testId}
+      className="w-full"
+      style={
+        height
+          ? { height: typeof height === "string" ? height : `${height}px` }
+          : undefined
+      }
+    />
+  );
+}'}, {'filename': 'src/components/CodeSnippet.tsx', 'status': 'added', 'patch': '@@ -0,0 +1,40 @@
+import * as React from "react"
+import { Card, CardContent, CardHeader } from "@/components/ui/card";
+import CodeMirrorEditor from "./CodeEditor";
+import CopyButton from "./CopyButton";
+
+interface CodeProps {
+    children: React.ReactNode;
+    node?: {
+      children?: Array<{
+        properties?: {
+          className?: string[];
+        };
+        children?: Array<{
+          value?: string;
+        }>;
+      }>;
+    };
+  }
+
+export default function CodeSnippet({ ...props }: CodeProps) {
+    const codeChildren = props.node?.children?.[0];
+    const className = codeChildren?.properties?.className?.[0];
+    const match = /language-(\w+)/.exec(className || '');
+    const code = codeChildren?.children?.[0]?.value;  
+  
+  
+    return (
+      <Card className="relative my-2 py-0 gap-2">
+        <CardHeader className="flex flex-row items-center justify-between py-1 px-4">
+          <span className="text-sm text-muted-foreground">
+            {match?.[1] || 'Raw code'}
+          </span>
+          <CopyButton content={code} />
+        </CardHeader>
+        <CardContent className="py-0 px-4">
+          <CodeMirrorEditor defaultValue={code} language={match?.[1]} readOnly />
+        </CardContent>
+      </Card>
+    );
+  }
\ No newline at end of file'}, {'filename': 'src/components/CopyButton.tsx', 'status': 'added', 'patch': '@@ -0,0 +1,70 @@
+import * as React from "react"
+import { Check, Copy } from 'lucide-react';
+import { useState } from 'react';
+import { toast } from 'sonner';
+
+import { Button } from '@/components/ui/button';
+import {
+  Tooltip,
+  TooltipContent,
+  TooltipProvider,
+  TooltipTrigger
+} from '@/components/ui/tooltip';
+
+interface Props {
+  content: unknown;
+  className?: string;
+}
+
+const CopyButton = ({ content, className }: Props) => {
+  const [copied, setCopied] = useState(false);
+
+  const copyToClipboard = async () => {
+    try {
+      const textToCopy =
+        typeof content === 'object'
+          ? JSON.stringify(content, null, 2)
+          : String(content);
+
+      await navigator.clipboard.writeText(textToCopy);
+      setCopied(true);
+
+      // Reset copied state after 2 seconds
+      setTimeout(() => {
+        setCopied(false);
+      }, 2000);
+    } catch (err) {
+      toast.error('Failed to copy: ' + String(err));
+    }
+  };
+
+  return (
+    <TooltipProvider delayDuration={100}>
+      <Tooltip>
+        <TooltipTrigger asChild>
+          <Button
+            onClick={copyToClipboard}
+            variant="ghost"
+            size="icon"
+            className={`text-muted-foreground ${className}`}
+          >
+            {copied ? (
+              <Check className="h-4 w-4" />
+            ) : (
+              <Copy className="h-4 w-4" />
+            )}
+          </Button>
+        </TooltipTrigger>
+        <TooltipContent>
+          <p>
+            {copied
+              ? 'Copied to clipboard'
+              : 'Copy'}
+          </p>
+        </TooltipContent>
+      </Tooltip>
+    </TooltipProvider>
+  );
+};
+
+export default CopyButton;'}, {'filename': 'src/components/Markdown.tsx', 'status': 'added', 'patch': '@@ -0,0 +1,189 @@
+import * as React from "react"
+import { useMemo } from 'react';
+import ReactMarkdown from 'react-markdown';
+import remarkGfm from 'remark-gfm';
+
+import { AspectRatio } from '@/components/ui/aspect-ratio';
+import { Card } from '@/components/ui/card';
+import { Separator } from '@/components/ui/separator';
+import {
+  Table,
+  TableBody,
+  TableCell,
+  TableHead,
+  TableHeader,
+  TableRow
+} from '@/components/ui/table';
+import { cn } from "@/utils/tailwind";
+import CodeSnippet from "./CodeSnippet";
+
+
+function omit<T extends object, K extends string>(obj: T, keys: K[]): Omit<T, K> {
+  const result = { ...obj } as any;
+  keys.forEach(key => delete result[key]);
+  return result;
+}
+
+interface Props {
+  children: string;
+  className?: string;
+}
+
+const Markdown = ({
+  className,
+  children
+}: Props) => {
+  const remarkPlugins = useMemo(() => {
+    let remarkPlugins = [
+      remarkGfm as any,
+    ];
+    return remarkPlugins;
+  }, []);
+
+  return (
+    <div className={cn('prose lg:prose-xl', className)}>
+      <ReactMarkdown
+        remarkPlugins={remarkPlugins}
+        components={{
+          code(props) {
+            return (
+              <code
+                {...omit(props, ['node'])}
+                className="relative rounded bg-muted px-[0.3rem] py-[0.2rem] font-mono text-sm font-semibold"
+              />
+            );
+          },
+          a(props) {
+            return (
+              <a
+                {...omit(props, ['node'])}
+                className="underline"
+                target="_blank"
+                rel="noopener noreferrer"
+              />
+            );
+          },
+          pre({ children, ...props }: any) {
+            return <CodeSnippet {...props} />;
+          },
+          img: (image: any) => {
+            return (
+              <div className="sm:max-w-sm md:max-w-md">
+                <AspectRatio
+                  ratio={16 / 9}
+                  className="bg-muted rounded-md overflow-hidden"
+                >
+                  <img
+                    src={image.src}
+                    alt={image.alt}
+                    className="h-full w-full object-contain"
+                  />
+                </AspectRatio>
+              </div>
+            );
+          },
+          blockquote(props) {
+            return (
+              <blockquote
+                {...omit(props, ['node'])}
+                className="mt-6 border-l-2 pl-6 italic"
+              />
+            );
+          },
+          em(props) {
+            return <span {...omit(props, ['node'])} className="italic" />;
+          },
+          strong(props) {
+            return <span {...omit(props, ['node'])} className="font-bold" />;
+          },
+          hr() {
+            return <Separator />;
+          },
+          ul(props) {
+            return (
+              <ul
+                {...omit(props, ['node'])}
+                className="my-3 ml-3 list-disc pl-2 [&>li]:mt-1"
+              />
+            );
+          },
+          ol(props) {
+            return (
+              <ol
+                {...omit(props, ['node'])}
+                className="my-3 ml-3 list-decimal pl-2 [&>li]:mt-1"
+              />
+            );
+          },
+          h1(props) {
+            return (
+              <h1
+                {...omit(props, ['node'])}
+                className="scroll-m-20 text-4xl font-extrabold tracking-tight lg:text-5xl mt-8 first:mt-0"
+              />
+            );
+          },
+          h2(props) {
+            return (
+              <h2
+                {...omit(props, ['node'])}
+                className="scroll-m-20 border-b pb-2 text-3xl font-semibold tracking-tight mt-8 first:mt-0"
+              />
+            );
+          },
+          h3(props) {
+            return (
+              <h3
+                {...omit(props, ['node'])}
+                className="scroll-m-20 text-2xl font-semibold tracking-tight mt-6 first:mt-0"
+              />
+            );
+          },
+          h4(props) {
+            return (
+              <h4
+                {...omit(props, ['node'])}
+                className="scroll-m-20 text-xl font-semibold tracking-tight mt-6 first:mt-0"
+              />
+            );
+          },
+          p(props) {
+            return (
+              <div
+                {...omit(props, ['node'])}
+                className="leading-7 [&:not(:first-child)]:mt-4 whitespace-pre-wrap break-words"
+                role="article"
+              />
+            );
+          },
+          table({ children, ...props }) {
+            return (
+              <Card className="[&:not(:first-child)]:mt-2 [&:not(:last-child)]:mb-2">
+                <Table {...(props as any)}>{children}</Table>
+              </Card>
+            );
+          },
+          thead({ children, ...props }) {
+            return <TableHeader {...(props as any)}>{children}</TableHeader>;
+          },
+          tr({ children, ...props }) {
+            return <TableRow {...(props as any)}>{children}</TableRow>;
+          },
+          th({ children, ...props }) {
+            return <TableHead {...(props as any)}>{children}</TableHead>;
+          },
+          td({ children, ...props }) {
+            return <TableCell {...(props as any)}>{children}</TableCell>;
+          },
+          tbody({ children, ...props }) {
+            return <TableBody {...(props as any)}>{children}</TableBody>;
+          }
+        }}
+      >
+        {children}
+      </ReactMarkdown>
+    </div>
+  );
+};
+
+export { Markdown };'}, {'filename': 'src/components/template/Footer.tsx', 'status': 'removed', 'patch': '@@ -1,10 +0,0 @@
