+import React from "react";
+import { Link } from "@tanstack/react-router";
+import { SidebarMenuItem, SidebarMenuButton, SidebarMenuAction } from "@/components/ui/sidebar";
+import { McpDropdownMenu } from "@/components/mcp-nav/McpDropdownMenu";
+import { toast } from "sonner";
+import { McpData } from "@/helpers/db/mcp-db";
+
+interface McpItemProps {
+  mcpItem: McpData;
+  deleteMcp: (mcpId: string, options: any) => void;
+}
+
+export function McpItem({
+  mcpItem,
+  deleteMcp,
+}: McpItemProps) {
+  // No state needed for edit functionality
+
+  // Handle delete MCP
+  const handleDeleteMcp = (mcpId: string, mcpName: string) => {
+    if (confirm(`Are you sure you want to delete the MCP "${mcpName}"?`)) {
+      deleteMcp(mcpId, {
+        onSuccess: () => {
+          toast.success(`MCP "${mcpName}" deleted successfully`);
+        },
+        onError: (error: unknown) => {
+          toast.error(`Failed to delete MCP: ${error instanceof Error ? error.message : 'Unknown error'}`);
+        }
+      });
+    }
+  };
+
+  return (
+    <SidebarMenuItem>
+      <Link to="/build-mcp" search={{ edit: undefined }}>
+        <SidebarMenuButton
+          className="flex-1 text-xs"
+        >
+          <div className="flex items-center">
+                <span className="cursor-pointer hover:text-primary transition-colors">
+                  {mcpItem.name}
+                </span>
+              </div>
+            </SidebarMenuButton>
+        </Link>
+        
+        <McpDropdownMenu
+          mcpId={mcpItem.id}
+          mcpName={mcpItem.name}
+          onDelete={handleDeleteMcp}
+        />
+      </SidebarMenuItem>
+  );
+}'}, {'filename': 'src/components/mcp-nav/index.tsx', 'status': 'added', 'patch': '@@ -0,0 +1,52 @@
+import React from "react";
+import { SidebarGroup, SidebarMenu, SidebarMenuItem } from "@/components/ui/sidebar";
+import { Plus } from "lucide-react";
+import { useMcps } from "@/hooks/useMcps";
+import { McpHeader } from "@/components/mcp-nav/McpHeader";
+import { McpItem } from "@/components/mcp-nav/McpItem";
+import { Loader } from "@/components/Loader";
+import { Link } from "@tanstack/react-router";
+
+export function McpNav() {
+  const { mcps, isLoading, error, isError, refetch, deleteMcp } = useMcps();
+
+  return (
+    <SidebarGroup>
+      <McpHeader isLoading={isLoading} refetch={refetch} />
+      <SidebarMenu>
+        {isLoading ? (
+          <SidebarMenuItem>
+            <div className="px-2 py-1 text-xs flex items-center justify-center">
+              <Loader className="mr-2" /> Loading MCPs...
+            </div>
+          </SidebarMenuItem>
+        ) : isError ? (
+          <SidebarMenuItem>
+            <div className="px-2 py-1 text-xs text-red-500">
+              Failed to load MCPs. Please try refreshing.
+              {error instanceof Error ? error.message : 'Unknown error'}
+            </div>
+          </SidebarMenuItem>
+        ) : mcps.length === 0 ? (
+          <SidebarMenuItem>
+            <Link to="/build-mcp" search={{ edit: undefined }}>
+              <div className="text-xs flex items-center px-2 py-1">
+                <Plus className="size-3 mr-2" /> Create MCP
+              </div>
+            </Link>
+          </SidebarMenuItem>
+        ) : (
+          <>
+            {mcps.map((mcpItem) => (
+              <McpItem
+                key={mcpItem.id}
+                mcpItem={mcpItem}
+                deleteMcp={deleteMcp}
+              />
+            ))}
+          </>
+        )}
+      </SidebarMenu>
+    </SidebarGroup>
+  );
+}'}, {'filename': 'src/helpers/db/mcp-db.ts', 'status': 'added', 'patch': '@@ -0,0 +1,250 @@
+import { app } from 'electron';
+import path from 'path';
+import fs from 'fs/promises';
+import { v4 as uuidv4 } from 'uuid';
+import fsSync from 'fs';
+
+// Define endpoint data structure
+export interface McpEndpoint {
+  apiId: string;
+  apiName: string;
+  method: string;
+  path: string;
+  operation: any;
+}
+
+// Define the MCP data structure that will be stored in files
+export interface McpData {
+  id: string;
+  name: string;
+  apiGroups: Record<string, {
+    serverUrl?: string;
+    useMockData: boolean;
+    auth: {
+      type: string;
+      [key: string]: any;
+    };
+    endpoints?: McpEndpoint[];
+  }>;
+  createdAt: string;
+  updatedAt: string;
+  // Optional credentials property populated by getMcpById when includeCredentials is true
+  credentials?: Record<string, any>;
+}
+
+// Define the directory where MCP data will be stored
+export const getMcpDataDir = () => {
+  const userDataPath = app.getPath('userData');
+  return path.join(userDataPath, 'mcp-data');
+};
+
+// Ensure the MCP data directory exists
+const ensureMcpDataDir = async () => {
+  const mcpDataDir = getMcpDataDir();
+  try {
+    await fs.mkdir(mcpDataDir, { recursive: true });
+  } catch (error) {
+    console.error('Failed to create MCP data directory:', error);
+    throw error;
+  }
+};
+
+// Get the file path for an MCP
+const getMcpFilePath = (mcpId: string) => {
+  return path.join(getMcpDataDir(), `${mcpId}.json`);
+};
+
+// Check if an MCP exists
+const mcpExists = async (mcpId: string): Promise<boolean> => {
+  try {
+    await fs.access(getMcpFilePath(mcpId));
+    return true;
+  } catch {
+    return false;
+  }
+};
+
+// Create a new MCP configuration with optional credentials
+const createMcp = async (mcpData: Omit<McpData, 'id' | 'createdAt' | 'updatedAt'>, credentials?: Record<string, any>): Promise<string> => {
+  await ensureMcpDataDir();
+  
+  // Generate a unique ID for the MCP
+  const mcpId = uuidv4();
+  
+  // Create the MCP data file with timestamps
+  const now = new Date().toISOString();
+  const fullMcpData: McpData = {
+    ...mcpData,
+    id: mcpId,
+    createdAt: now,
+    updatedAt: now
+  };
+  
+  await fs.writeFile(getMcpFilePath(mcpId), JSON.stringify(fullMcpData, null, 2));
+  
+  // If credentials are provided, store them
+  if (credentials && Object.keys(credentials).length > 0) {
+    try {
+      await keytar.setPassword(SERVICE_NAME, `${ACCOUNT_NAME}-${mcpId}`, JSON.stringify(credentials));
+    } catch (credError) {
+      console.error(`Error storing credentials for MCP with ID ${mcpId}:`, credError);
+      // Continue even if credential storage fails
+    }
+  }
+  
+  return mcpId;
+};
+
+// List all MCPs
+const listMcps = async (): Promise<McpData[]> => {
+  await ensureMcpDataDir();
+  
+  try {
+    const files = await fs.readdir(getMcpDataDir());
+    // Filter only MCP data files
+    const mcpFiles = files.filter(file => file.endsWith('.json'));
+    
+    const mcps: McpData[] = [];
+    
+    for (const file of mcpFiles) {
+      try {
+        const filePath = path.join(getMcpDataDir(), file);
+        const fileContent = await fs.readFile(filePath, 'utf-8');
+        const mcpData = JSON.parse(fileContent) as McpData;
+        mcps.push(mcpData);
+      } catch (error) {
+        console.error(`Error reading MCP file ${file}:`, error);
+        // Continue with other files
+      }
+    }
+    
+    return mcps;
+  } catch (error) {
+    console.error('Error listing MCPs:', error);
+    return [];
+  }
+};
+
+// Import keytar for credentials access
+import keytar from 'keytar';
+
+// Service name for keytar - must match the one in mcp-listeners.ts
+const SERVICE_NAME = "toolman-mcp-credentials";
+// Account name for keytar - must match the one in mcp-listeners.ts
+const ACCOUNT_NAME = "tar";
+
+// Get an MCP by ID
+const getMcpById = async (id: string, includeCredentials: boolean = false): Promise<McpData | null> => {
+  if (!await mcpExists(id)) {
+    return null;
+  }
+  
+  try {
+    const fileContent = await fs.readFile(getMcpFilePath(id), 'utf-8');
+    const mcpData = JSON.parse(fileContent) as McpData;
+    
+    // If requested, fetch and include credentials
+    if (includeCredentials) {
+      try {
+        const credentialsJson = await keytar.getPassword(SERVICE_NAME, `${ACCOUNT_NAME}-${id}`);
+        if (credentialsJson) {
+          const credentials = JSON.parse(credentialsJson);
+          
+          // Add credentials to the MCP data
+          mcpData.credentials = credentials;
+        }
+      } catch (credError) {
+        console.error(`Error fetching credentials for MCP with ID ${id}:`, credError);
+        // Continue without credentials if there's an error
+      }
+    }
+    
+    return mcpData;
+  } catch (error) {
+    console.error(`Error getting MCP with ID ${id}:`, error);
+    return null;
+  }
+};
+
+// Update an MCP - completely rewrites the file with new data
+const updateMcp = async (id: string, mcpData: Omit<McpData, 'id' | 'createdAt' | 'updatedAt'>): Promise<boolean> => {
+  if (!await mcpExists(id)) {
+    return false;
+  }
+  
+  try {
+    // Get existing MCP data just for the id, createdAt fields
+    const existingMcpData = await getMcpById(id);
+    if (!existingMcpData) {
+      return false;
+    }
+    
+    // Create a completely new MCP data object with the provided data
+    // Only preserve the id and createdAt from the existing data
+    const updatedMcpData: McpData = {
+      id: existingMcpData.id,
+      createdAt: existingMcpData.createdAt,
+      updatedAt: new Date().toISOString(),
+      name: mcpData.name,
+      apiGroups: mcpData.apiGroups
+    };
+    
+    // Write the completely new data to the file
+    await fs.writeFile(getMcpFilePath(id), JSON.stringify(updatedMcpData, null, 2));
+    
+    return true;
+  } catch (error) {
+    console.error(`Error updating MCP with ID ${id}:`, error);
+    return false;
+  }
+};
+
+// Delete an MCP
+const deleteMcp = async (id: string): Promise<boolean> => {
+  if (!await mcpExists(id)) {
+    return false;
+  }
+  
+  try {
+    // Delete the MCP file
+    await fs.unlink(getMcpFilePath(id));
+    return true;
+  } catch (error) {
+    console.error(`Error deleting MCP with ID ${id}:`, error);
+    return false;
+  }
+};
+
+// Save credentials for an MCP
+const saveCredentials = async (mcpId: string, credentials: Record<string, any>): Promise<boolean> => {
+  try {
+    await keytar.setPassword(SERVICE_NAME, `${ACCOUNT_NAME}-${mcpId}`, JSON.stringify(credentials));
+    return true;
+  } catch (error) {
+    console.error(`Error saving credentials for MCP with ID ${mcpId}:`, error);
+    return false;
+  }
+};
+
+// Clear credentials for an MCP
+const clearCredentials = async (mcpId: string): Promise<boolean> => {
+  try {
+    await keytar.deletePassword(SERVICE_NAME, `${ACCOUNT_NAME}-${mcpId}`);
+    return true;
+  } catch (error) {
+    console.error(`Error clearing credentials for MCP with ID ${mcpId}:`, error);
+    return false;
+  }
+};
+
+// Export the MCP database functions
+export const mcpDb = {
+  createMcp,
+  listMcps,
+  getMcpById,
+  updateMcp,
+  deleteMcp,
+  mcpExists,
+  saveCredentials,
+  clearCredentials
+};'}, {'filename': 'src/helpers/ipc/context-exposer.ts', 'status': 'modified', 'patch': '@@ -2,10 +2,12 @@ import { exposeThemeContext } from "./theme/theme-context";
 import { exposeWindowContext } from "./window/window-context";
 import { exposeOpenApiContext } from "./openapi/openapi-context";
 import { exposeAuthContext } from "./auth/auth-context";
+import { exposeMcpContext } from "./mcp/mcp-context-exposer";

 export default function exposeContexts() {
   exposeWindowContext();
   exposeThemeContext();
   exposeOpenApiContext();
   exposeAuthContext();
+  exposeMcpContext();
 }'}, {'filename': 'src/helpers/ipc/listeners-register.ts', 'status': 'modified', 'patch': '@@ -3,10 +3,12 @@ import { addThemeEventListeners } from "./theme/theme-listeners";
 import { addWindowEventListeners } from "./window/window-listeners";
 import { registerOpenApiListeners } from "./openapi/openapi-listeners";
 import { registerAuthListeners } from "./auth/auth-listeners";
+import { registerMcpListeners } from "./mcp/mcp-listeners";

 export default function registerListeners(mainWindow: BrowserWindow) {
   addWindowEventListeners(mainWindow);
   addThemeEventListeners();
   registerOpenApiListeners();
   registerAuthListeners();
+  registerMcpListeners();
 }'}, {'filename': 'src/helpers/ipc/mcp/mcp-channels.ts', 'status': 'added', 'patch': "@@ -0,0 +1,9 @@
+// Channel names for MCP operations
+export const CREATE_MCP_CHANNEL = 'create-mcp';
+export const LIST_MCPS_CHANNEL = 'list-mcps';
+export const GET_MCP_CHANNEL = 'get-mcp';
+export const UPDATE_MCP_CHANNEL = 'update-mcp';
+export const DELETE_MCP_CHANNEL = 'delete-mcp';
+export const MCP_GET_CREDENTIALS_CHANNEL = 'mcp-get-credentials';
+export const MCP_SAVE_CREDENTIALS_CHANNEL = 'mcp-save-credentials';
+export const MCP_CLEAR_CREDENTIALS_CHANNEL = 'mcp-clear-credentials';"}, {'filename': 'src/helpers/ipc/mcp/mcp-client.ts', 'status': 'added', 'patch': "@@ -0,0 +1,39 @@
+import { ipcRenderer } from 'electron';
+import {
+  CREATE_MCP_CHANNEL,
+  LIST_MCPS_CHANNEL,
+  GET_MCP_CHANNEL,
+  UPDATE_MCP_CHANNEL,
+  DELETE_MCP_CHANNEL,
+  MCP_GET_CREDENTIALS_CHANNEL,
+  MCP_SAVE_CREDENTIALS_CHANNEL,
+  MCP_CLEAR_CREDENTIALS_CHANNEL
+} from './mcp-channels';
+import { McpData } from '@/helpers/db/mcp-db';
+
+// Client-side functions to communicate with the main process
+export const mcpClient = {
+  createMcp: (mcpData: Omit<McpData, 'id' | 'createdAt' | 'updatedAt'>) => 
+    ipcRenderer.invoke(CREATE_MCP_CHANNEL, mcpData),
+    
+  listMcps: () => 
+    ipcRenderer.invoke(LIST_MCPS_CHANNEL),
+    
+  getMcp: (id: string) => 
+    ipcRenderer.invoke(GET_MCP_CHANNEL, id),
+    
+  updateMcp: (id: string, data: Partial<Omit<McpData, 'id' | 'createdAt' | 'updatedAt'>>) => 
+    ipcRenderer.invoke(UPDATE_MCP_CHANNEL, { id, data }),
+    
+  deleteMcp: (id: string) => 
+    ipcRenderer.invoke(DELETE_MCP_CHANNEL, id),
+    
+  getCredentials: (mcpId: string) => 
+    ipcRenderer.invoke(MCP_GET_CREDENTIALS_CHANNEL, mcpId),
+    
+  saveCredentials: (mcpId: string, credentials: any) => 
+    ipcRenderer.invoke(MCP_SAVE_CREDENTIALS_CHANNEL, mcpId, credentials),
+    
+  clearCredentials: (mcpId: string) => 
+    ipcRenderer.invoke(MCP_CLEAR_CREDENTIALS_CHANNEL, mcpId)
+};"}, {'filename': 'src/helpers/ipc/mcp/mcp-context-exposer.ts', 'status': 'added', 'patch': "@@ -0,0 +1,40 @@
+import { contextBridge, ipcRenderer } from 'electron';
+import {
+  CREATE_MCP_CHANNEL,
+  LIST_MCPS_CHANNEL,
+  GET_MCP_CHANNEL,
+  UPDATE_MCP_CHANNEL,
+  DELETE_MCP_CHANNEL,
+  MCP_GET_CREDENTIALS_CHANNEL,
+  MCP_SAVE_CREDENTIALS_CHANNEL,
+  MCP_CLEAR_CREDENTIALS_CHANNEL
+} from './mcp-channels';
+import { McpData } from '@/helpers/db/mcp-db';
+
+export function exposeMcpContext() {
+  contextBridge.exposeInMainWorld('mcpApi', {
+    createMcp: (mcpData: Omit<McpData, 'id' | 'createdAt' | 'updatedAt'>) => 
+      ipcRenderer.invoke(CREATE_MCP_CHANNEL, mcpData),
+      
+    listMcps: () => 
+      ipcRenderer.invoke(LIST_MCPS_CHANNEL),
+      
+    getMcp: (id: string) => 
+      ipcRenderer.invoke(GET_MCP_CHANNEL, id),
+      
+    updateMcp: (id: string, data: Partial<Omit<McpData, 'id' | 'createdAt' | 'updatedAt'>>) => 
+      ipcRenderer.invoke(UPDATE_MCP_CHANNEL, { id, data }),
+      
+    deleteMcp: (id: string) => 
+      ipcRenderer.invoke(DELETE_MCP_CHANNEL, id),
+      
+    getCredentials: (mcpId: string) => 
+      ipcRenderer.invoke(MCP_GET_CREDENTIALS_CHANNEL, mcpId),
+      
+    saveCredentials: (mcpId: string, credentials: any) => 
+      ipcRenderer.invoke(MCP_SAVE_CREDENTIALS_CHANNEL, mcpId, credentials),
+      
+    clearCredentials: (mcpId: string) => 
+      ipcRenderer.invoke(MCP_CLEAR_CREDENTIALS_CHANNEL, mcpId)
+  });
+}"}, {'filename': 'src/helpers/ipc/mcp/mcp-listeners.ts', 'status': 'added', 'patch': '@@ -0,0 +1,164 @@
+import { ipcMain } from "electron";
+import keytar from "keytar";
+import {
+  CREATE_MCP_CHANNEL,
+  LIST_MCPS_CHANNEL,
+  GET_MCP_CHANNEL,
+  UPDATE_MCP_CHANNEL,
+  DELETE_MCP_CHANNEL,
+  MCP_GET_CREDENTIALS_CHANNEL,
+  MCP_SAVE_CREDENTIALS_CHANNEL,
+  MCP_CLEAR_CREDENTIALS_CHANNEL
+} from "./mcp-channels";
+import { mcpDb, McpData } from "@/helpers/db/mcp-db";
+
+// Service name for keytar - used for storing credentials
+const SERVICE_NAME = "toolman-mcp-credentials";
+// Account name for keytar - used as a key for storing MCP credentials
+const ACCOUNT_NAME = "tar";
+
+export function registerMcpListeners() {
+  // Create a new MCP configuration
+  ipcMain.handle(CREATE_MCP_CHANNEL, async (_, mcpData: Omit<McpData, 'id' | 'createdAt' | 'updatedAt'>) => {
+    try {
+      const mcpId = await mcpDb.createMcp(mcpData);
+      return {
+        success: true,
+        message: "MCP configuration created successfully",
+        mcpId
+      };
+    } catch (error) {
+      console.error("Error creating MCP configuration:", error);
+      return {
+        success: false,
+        message: error instanceof Error ? error.message : "Unknown error occurred"
+      };
+    }
+  });
+
+  // List all MCPs
+  ipcMain.handle(LIST_MCPS_CHANNEL, async () => {
+    try {
+      const mcps = await mcpDb.listMcps();
+      return {
+        success: true,
+        mcps
+      };
+    } catch (error) {
+      console.error("Error listing MCPs:", error);
+      return {
+        success: false,
+        message: error instanceof Error ? error.message : "Unknown error occurred"
+      };
+    }
+  });
+
+  // Get a specific MCP by ID
+  ipcMain.handle(GET_MCP_CHANNEL, async (_, id: string) => {
+    try {
+      const mcpData = await mcpDb.getMcpById(id);
+      
+      if (!mcpData) {
+        return {
+          success: false,
+          message: `MCP with ID ${id} not found`
+        };
+      }
+      
+      return {
+        success: true,
+        mcp: mcpData
+      };
+    } catch (error) {
+      console.error(`Error getting MCP with ID ${id}:`, error);
+      return {
+        success: false,
+        message: error instanceof Error ? error.message : "Unknown error occurred"
+      };
+    }
+  });
+
+  // Update an MCP
+  ipcMain.handle(UPDATE_MCP_CHANNEL, async (_, request: { id: string; data: Partial<Omit<McpData, 'id' | 'createdAt' | 'updatedAt'>> }) => {
+    try {
+      const { id, data } = request;
+      const success = await mcpDb.updateMcp(id, data);
+      
+      if (!success) {
+        return {
+          success: false,
+          message: `MCP with ID ${id} not found`
+        };
+      }
+      
+      return {
+        success: true,
+        message: "MCP updated successfully"
+      };
+    } catch (error) {
+      console.error("Error updating MCP:", error);
+      return {
+        success: false,
+        message: error instanceof Error ? error.message : "Unknown error occurred"
+      };
+    }
+  });
+
+  // Delete an MCP
+  ipcMain.handle(DELETE_MCP_CHANNEL, async (_, id: string) => {
+    try {
+      const success = await mcpDb.deleteMcp(id);
+      
+      if (!success) {
+        return {
+          success: false,
+          message: `MCP with ID ${id} not found`
+        };
+      }
+      
+      return {
+        success: true,
+        message: "MCP deleted successfully"
+      };
+    } catch (error) {
+      console.error(`Error deleting MCP with ID ${id}:`, error);
+      return {
+        success: false,
+        message: error instanceof Error ? error.message : "Unknown error occurred"
+      };
+    }
+  });
+
+  // Get credentials for a specific MCP
+  ipcMain.handle(MCP_GET_CREDENTIALS_CHANNEL, async (_, mcpId: string) => {
+    try {
+      const credentials = await keytar.getPassword(SERVICE_NAME, `${ACCOUNT_NAME}-${mcpId}`);
+      return credentials ? JSON.parse(credentials) : null;
+    } catch (error) {
+      console.error("Error retrieving MCP credentials:", error);
+      return null;
+    }
+  });
+
+  // Save credentials for a specific MCP
+  ipcMain.handle(MCP_SAVE_CREDENTIALS_CHANNEL, async (_, mcpId: string, credentials: any) => {
+    try {
+      await keytar.setPassword(SERVICE_NAME, `${ACCOUNT_NAME}-${mcpId}`, JSON.stringify(credentials));
+      return true;
+    } catch (error) {
+      console.error("Error saving MCP credentials:", error);
+      return false;
+    }
+  });
+
+  // Clear credentials for a specific MCP
+  ipcMain.handle(MCP_CLEAR_CREDENTIALS_CHANNEL, async (_, mcpId: string) => {
+    try {
+      await keytar.deletePassword(SERVICE_NAME, `${ACCOUNT_NAME}-${mcpId}`);
