+import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
+import { McpData } from '@/helpers/db/mcp-db';
+
+// Query key for MCPs
+export const MCP_QUERY_KEY = 'mcps';
+
+export function useMcps() {
+  const queryClient = useQueryClient();
+
+  // Fetch all MCPs
+  const {
+    data = { mcps: [] },
+    isLoading,
+    isError,
+    error,
+    refetch
+  } = useQuery({
+    queryKey: [MCP_QUERY_KEY],
+    queryFn: async () => {
+      const result = await window.mcpApi.listMcps();
+      if (!result.success) {
+        throw new Error(result.message || 'Failed to fetch MCPs');
+      }
+      return result;
+    }
+  });
+
+  const createMcpMutation = useMutation({
+    mutationFn: async ({ mcpData, credentials }: { mcpData: Omit<McpData, 'id' | 'createdAt' | 'updatedAt'>, credentials?: Record<string, any> }) => {
+      const result = await window.mcpApi.createMcp(mcpData);
+      if (!result.success) {
+        throw new Error(result.message || 'Failed to create MCP');
+      }
+      
+      // If credentials are provided, save them
+      if (credentials && Object.keys(credentials).length > 0 && result.mcpId) {
+        await window.mcpApi.saveCredentials(result.mcpId, credentials);
+      }
+      
+      return result;
+    },
+    onSuccess: () => {
+      queryClient.invalidateQueries({ queryKey: [MCP_QUERY_KEY] });
+    }
+  });
+  
+  // Update an MCP
+  const updateMcpMutation = useMutation({
+    mutationFn: async ({ mcpId, mcpData, credentials }: { mcpId: string, mcpData: Omit<McpData, 'id' | 'createdAt' | 'updatedAt'>, credentials?: Record<string, any> }) => {
+      const result = await window.mcpApi.updateMcp(mcpId, mcpData);
+      if (!result.success) {
+        throw new Error(result.message || 'Failed to update MCP');
+      }
+      
+      // If credentials are provided, save them
+      if (credentials && Object.keys(credentials).length > 0) {
+        await window.mcpApi.saveCredentials(mcpId, credentials);
+      }
+      
+      return result;
+    },
+    onSuccess: () => {
+      queryClient.invalidateQueries({ queryKey: [MCP_QUERY_KEY] });
+    }
+  });
+
+  // Delete an MCP
+  const deleteMcpMutation = useMutation({
+    mutationFn: async (mcpId: string) => {
+      const result = await window.mcpApi.deleteMcp(mcpId);
+      if (!result.success) {
+        throw new Error(result.message || 'Failed to delete MCP');
+      }
+      return result;
+    },
+    onSuccess: () => {
+      queryClient.invalidateQueries({ queryKey: [MCP_QUERY_KEY] });
+    }
+  });
+
+
+
+  return {
+    mcps: data.mcps as McpData[],
+    isLoading,
+    isError,
+    error,
+    refetch,
+    createMcp: createMcpMutation.mutate,
+    updateMcp: updateMcpMutation.mutate,
+    deleteMcp: deleteMcpMutation.mutate,
+  };
+}"}, {'filename': 'src/main.ts', 'status': 'modified', 'patch': '@@ -8,6 +8,7 @@ import {
