+FROM postgres:17 AS base
+
+FROM base AS pg_mooncake
+
+RUN apt update \
+ && apt install -y \
+    cmake \
+    curl \
+    git \
+    g++ \
+    liblz4-dev \
+    pkg-config \
+    postgresql-server-dev-17 \
+ && rm -rf /var/lib/apt/lists/*
+
+RUN curl https://sh.rustup.rs | sh -s -- -y
+
+ENV PATH="/root/.cargo/bin:$PATH"
+
+RUN cargo install --locked cargo-pgrx@0.14.3 \
+ && cargo pgrx init --pg17=$(which pg_config)
+
+COPY . /build/pg_mooncake
+
+RUN cd /build/pg_mooncake \
+ && make clean \
+ && make package
+
+FROM base
+
+COPY --from=pg_mooncake /build/pg_mooncake/target/release/pg_mooncake-pg17/ /
+
+RUN cat >> /usr/share/postgresql/postgresql.conf.sample <<EOF
+shared_preload_libraries = 'pg_mooncake'
+wal_level = logical
+EOF'}, {'filename': 'Makefile', 'status': 'added', 'patch': '@@ -0,0 +1,34 @@
+MAKEFLAGS := --no-print-directory
+
+.PHONY: help clean format package pgduckdb run test
+
+help:
+	@echo "Usage: make <COMMAND>"
+	@echo ""
+	@echo "Commands:"
+	@echo "  run        Build and run pg_mooncake for development"
+	@echo "  format     Format the codebase"
+	@echo "  test       Run all tests"
+	@echo "  package    Build an installation package for release"
+	@echo "  clean      Remove all build artifacts"
+
+clean:
+	@$(MAKE) -C pg_duckdb clean-all
+	@cargo clean
+
+format:
+	@$(MAKE) -C pg_duckdb format-all
+	@cargo fmt
+	@cargo clippy
+
+package: pgduckdb
+	@cargo pgrx package
+
+pgduckdb:
+	@$(MAKE) -C pg_duckdb all-static-lib duckdb DUCKDB_BUILD=ReleaseStatic DUCKDB_GEN=make
+
+run: pgduckdb
+	@cargo pgrx run
+
+test: pgduckdb
+	@cargo pgrx regress --resetdb'}, {'filename': 'build.rs', 'status': 'added', 'patch': '@@ -0,0 +1,17 @@
