+use super::server;
+use pgrx::bgworkers::{BackgroundWorker, BackgroundWorkerBuilder, SignalWakeFlags};
+use pgrx::prelude::*;
+use std::time::Duration;
+
+pub(crate) fn init() {
+    BackgroundWorkerBuilder::new("pg_moonlink")
+        .set_library("pg_mooncake")
+        .set_function("pgmoonlink_main")
+        .enable_shmem_access(None)
+        .set_restart_time(Some(Duration::from_secs(15)))
+        .load();
+}
+
+#[pg_guard]
+#[no_mangle]
+extern "C-unwind" fn pgmoonlink_main(_arg: pg_sys::Datum) {
+    std::env::set_var("RUST_BACKTRACE", "1");
+    BackgroundWorker::attach_signal_handlers(SignalWakeFlags::SIGTERM);
+    server::start();
+}'}, {'filename': 'src/pgmoonlink/client.rs', 'status': 'added', 'patch': '@@ -0,0 +1,65 @@
+use super::common::*;
+use bincode::{Decode, Encode};
+use std::io::{Read, Write};
+use std::os::unix::net::UnixStream;
+use std::sync::{LazyLock, Mutex};
+
+static STREAM: LazyLock<Mutex<UnixStream>> =
+    LazyLock::new(|| Mutex::new(UnixStream::connect(SOCKET_PATH).unwrap()));
+
+pub(crate) fn create_snapshot(database_id: u32, table_id: u32, lsn: u64) {
+    let mut stream = STREAM.lock().unwrap();
+    let table_id = TableId {
+        database_id,
+        table_id,
+    };
+    write(&mut stream, &Request::CreateSnapshot { table_id, lsn });
+    read(&mut stream)
+}
+
+pub(crate) fn create_table(database_id: u32, table_id: u32, table: String, uri: String) {
+    let mut stream = STREAM.lock().unwrap();
+    let table_id = TableId {
+        database_id,
+        table_id,
+    };
+    write(
+        &mut stream,
+        &Request::CreateTable {
+            table_id,
+            table,
+            uri,
+        },
+    );
+    read(&mut stream)
+}
+
+pub(super) fn scan_table_begin(table_id: TableId, lsn: u64) -> Vec<u8> {
+    let mut stream = STREAM.lock().unwrap();
+    write(&mut stream, &Request::ScanTableBegin { table_id, lsn });
+    read(&mut stream)
+}
+
+pub(super) fn scan_table_end(table_id: TableId) {
+    let mut stream = STREAM.lock().unwrap();
+    write(&mut stream, &Request::ScanTableEnd { table_id });
+    read(&mut stream)
+}
+
+fn write<E: Encode>(stream: &mut UnixStream, data: &E) {
+    let bytes = bincode::encode_to_vec(data, BINCODE_CONFIG).unwrap();
+    let len = u32::try_from(bytes.len()).unwrap();
+    stream.write_all(&len.to_ne_bytes()).unwrap();
+    stream.write_all(&bytes).unwrap();
+}
+
+fn read<D: Decode<()>>(stream: &mut UnixStream) -> D {
+    let mut buf = [0; 4];
+    stream.read_exact(&mut buf).unwrap();
+    let len = u32::from_ne_bytes(buf);
+    let mut bytes = vec![0; len as usize];
+    stream.read_exact(&mut bytes).unwrap();
+    bincode::decode_from_slice(&bytes, BINCODE_CONFIG)
+        .unwrap()
+        .0
+}'}, {'filename': 'src/pgmoonlink/common.rs', 'status': 'added', 'patch': '@@ -0,0 +1,31 @@
+use bincode::{config, Decode, Encode};
+
+pub(super) const BINCODE_CONFIG: config::Configuration = config::standard();
+
+pub(super) const SOCKET_PATH: &str = "pg_moonlink.sock";
+
+#[derive(Clone, Debug, PartialEq, Eq, Hash, Encode, Decode)]
+pub(super) struct TableId {
+    pub(super) database_id: u32,
+    pub(super) table_id: u32,
+}
+
+#[derive(Debug, Encode, Decode)]
+pub(super) enum Request {
+    CreateSnapshot {
+        table_id: TableId,
+        lsn: u64,
+    },
+    CreateTable {
+        table_id: TableId,
+        table: String,
+        uri: String,
+    },
+    ScanTableBegin {
+        table_id: TableId,
+        lsn: u64,
+    },
+    ScanTableEnd {
+        table_id: TableId,
+    },
+}'}, {'filename': 'src/pgmoonlink/ffi.rs', 'status': 'added', 'patch': '@@ -0,0 +1,32 @@
+use super::client::{scan_table_begin, scan_table_end};
+use super::common::TableId;
+use pgrx::prelude::*;
+
+#[pg_guard]
+#[no_mangle]
+extern "C-unwind" fn mooncake_scan_table_begin(
+    table_id: u32,
+    lsn: u64,
+    data: *mut *mut u8,
+    len: *mut usize,
+) {
