[{'filename': 'sdk/monitor/azure-monitor-query/src/main/java/com/azure/monitor/query/implementation/metrics/models/MetricsHelper.java', 'status': 'modified', 'patch': '@@ -330,33 +330,46 @@ public static String toMetricsTimespan(QueryTimeInterval timeInterval) {

         // If we have both start and end times, use them directly
